  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (173::BIGINT, 'El curso fue buenísimo y los trabajos fueron divertidos; el profe cae bien y no califica muy duro.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2026-08-06T00:00:00+00:00'::TIMESTAMPTZ, '245a89de4e9dc35b573b143f683a1655bb007030969333a7018ee4cf88366ec2'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Se hacen grupos y cada grupo expone sobre una película que hayan visto en clase, deja lecturas de 10-15 páginas, a veces menos, sobre éstas lecturas hace los quizes. No falte a clases, deja un trabajo final de hacer un cortometraje de unos 2 minutos. Eos sí, aprovecha cada segundo de clase.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Clases largas']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'ad4b63e2f10f3f5dfc8c0acba179c9784671f7c2631c60ef31c0c0bc545c99db'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'Es un curso muy bonito y relajante, el profe deja trabajos muy creativos solo que, si es estricto al calificar. Si tomar en cuenta la asistencia porque trabaja con avances y si faltas a la clase pierdes ese %, además la mayoría de los trabajos son grupales. Lo recomiendo si te gusta y sabes del área'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2026-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'd6538584b5e541eeb1058cd886896312a462ba26da7bbbd37f4051f9010597c9'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Yo la vdd no sabia dibujar tan bien y no me fue tan mal, creo que el curso lo estimula a uno para que sepa hacer las cosas a huevazo. Lo recomiendo SOLO si lo hace con compas.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2026-06-26T00:00:00+00:00'::TIMESTAMPTZ, '2aa3dccef0382cd6e5d0fd9f63d0f4a7f43a88f0597d40ffbbfb049c527d695a'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Es un curso muy fácil, los proyectos son grupales, hay que ir a un par de exposiciones de arte. El profe explica bien y ayuda en lo que uno necesite.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2026-01-31T00:00:00+00:00'::TIMESTAMPTZ, '44a841128a46363d468cd0ed3e3ecaf103168cc4beab79d822df80ee4f8b3acf'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Cae bien y se nota que le apasiona lo que hace, si le gusta el arte de fijo le va a gustar el curso y se le va a hacer como un despeje del tec'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-25T00:00:00+00:00'::TIMESTAMPTZ, '0e3486eaa84f43777275aa0d9da9c6ee46cfc8d5371abf488ab44c2a0444965a'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Pienso que es fácil el curso y fue entretenido, lo único que no me gustó del todo es que casi todo se hiciera viendo una imágen y copiandola al papel, por lo que no hay mucha originalidad'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación']::TEXT[], '2025-07-23T00:00:00+00:00'::TIMESTAMPTZ, '0095f651c62f6b9e3a88b6a1ce647d7b24341a7e46c3537b1cad0e2ba27599e5'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'El profe es relajado y cae bien, en mi opinión la mejor cultural si a uno le gusta dibujar y pintar. Es bueno tener un curso así para olvidarse un rato que uno es del TEC'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '53093493b2c38ca8ecb941f87c21afdf4b70878e7ad96d00d541ed087f476f4b'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Buen profe, creo que la mejor cultural la verdad. Entretenida, talvez algo tediosa si no le gusta el arte, pero esta bien, el profe da bien la clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-21T00:00:00+00:00'::TIMESTAMPTZ, '555e6856407b918ce3dd8d70ecf3f9887e143c3f1c93ed1fe65c2ada3b60d0ef'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Demasiado para ser una cultural. Cree que es requisito del curso saber de dibujo y pintura, hay una unidad que la califica según lo que a él le parezca que quedó lindo y con "esfuerzo". Pide ir a mínimo 4 exposiciones de arte, algunas en SJ, y valen 5% c/u.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'c5dcb1e3709be1d24bd16293cebc4fc69d14c441bf3cdf047b2cb1b0590a1bfe'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-05-18T00:00:00+00:00'::TIMESTAMPTZ, '8275ff09c29cd9f6436095b31b348291a4b9cd84ef512cbdb11daedd30003bc6'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'No lo recomiendo a menos que usted ya sepa dibujar. Si usted espera que el profesor explique teoría de dibujo, o vaya lentamente explicando técnicas diferentes no matricule con él, le da los materiales y lo deja a usted a la suerte, lo pone a hacer dibujos complicados aún si usted nunca ha dibujado.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-05-18T00:00:00+00:00'::TIMESTAMPTZ, '331c56eaa06a4b26b8924a331255bbb91ed7451a816f2f8365a366c229a613d4'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'El curso es bastante entretenido, todos los trabajos son sencillos y se hacen en clase. Lo único incomodo es tener que asistir a las exposiciones.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'f1c2a1f1d73a3537e317049971e36c4d3245437a6fbee022db739926f7068c2a'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Pasar el curso es sencillo, solo vaya a clase y a las exposiciones (puede que algunas no sean para todo el mundo).'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, '233a983f2721812aee0bd20f6e5121fdab85d559e746803858d50c8d16ae5883'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'El curso no requiere trabajo extra clase. Todas las entregas se realizan en tiempo lectivo. Es obligatorio asistir a las exposiciones, en algunos casos estas pasadas de tono. El profe tiene una actitud un tanto prepotente pero el curso se pasa entregando todo.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '12f84a4a57d5568c6eb08e164f12d7b83e333780458ed3c6bfdc24dabe208c43'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'El curso es muy chill y entretenido, en realidad es fácil de pasar entregando las tareas semanales. El profe es muy buena gente. Lo recomiendo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'a22f8d6cf39b42b6b8f12c4ed1f7359024e8bed358afd4123ecca9b881819418'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Es muy fácil y entretenido, el profe es amable :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'd3f8030aa3e13f88afe8fa35fc62179c69f005a086129326fbcf303b2eddba5c'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'El profe es muy buena gente. Sus clases son muy tranqui y entretenidas. Se ven temas interesantes y las tareas también lo son. Es un curso fácil y divertido.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-16T00:00:00+00:00'::TIMESTAMPTZ, '81af988dfb30a7ee4ddb2c2d345619d1d06c1a08c2b34c03e8ae6dbbb257dc6e'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'El curso se pasa fácil, es cuestión de entregar todas las tareas que pide y esforzarse por hacerlas bien. Es algo crítico con los trabajos pero al final califica suave. Importante ir a las exposiciones'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2022-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'a9bfc68ccfe354c64b3881b8601bd2c15bd85a43e7e026ba81d015feaf0bbf9c'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Buen profe, si se esfuerza se pasa fácil, en la pintura si se requieren comprar materiales, ahí no calificó muy rudo. En la fotografía fácil también pero le gustaban las cosas bien echas, en el trabajo final de fotografía calificó más rudo, y requiere de tiempo.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '61e930ab21a438c0f9fd486c0b2281cfcfe53aaaca4d510226eaf652a2b45d07'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Es un profe súper atento con sus estudiantes. Si es cierto que los trabajos requieren de su tiempo pero con que los lleve al día y le vaya enseñando al profe siempre da retroalimentación de como mejorar y casi que se garantiza un 100 en el portafolio final. Súper buena nota.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, '09f5f56a33c8aaf0d8c713224b8c916e6f9f29d430303299f1596c8cf9518319'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Facil si sabe dibujar. Es demandante, todas las semanas habia trabajos (explicados en videos), especialmente en la parte de fotografia (que hay que hacer cortos). Se interesa por las dudas.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2022-06-04T00:00:00+00:00'::TIMESTAMPTZ, 'e85c270ab2a40311096b24aea020e2c6e7100ef87cfa740199fcab7eee9a5797'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Si usted sabe dibujar, y las reglas de composición, y cómo hacer un cortometraje, está excelente. Pero el profe es muy, MUY demandante con todos los trabajos. Deja 1 por semana. Para 0 créditos quita mucho tiempo, especialmente cuando es una semana apocalíptica. Hay mejores para una cultural.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2022-06-01T00:00:00+00:00'::TIMESTAMPTZ, '769302558f1e7d51ccec9080b43a5f80fc67fedc55cfd2cba205896b924b8260'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'En clases es buena gente, pero al calificar es demasiado pedante. Le tiene que gustar su trabajo o le va a ir mal y va a hacerle comentarios despectivos. Se le olvida que es un curso de 0 créditos. Sus críticas no son constructivas. No matriculen con él a menos de que sean MUY buenos en artes.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Deja trabajos largos']::TEXT[], '2022-04-09T00:00:00+00:00'::TIMESTAMPTZ, 'abb9f8cd86d0e0cb6c4c2697da07fe87a98e8b05affaaacd5b82d26cea53a07e'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Un excelente profe que disfruta dar su clase. No califica nada duro, pero parece olvidar que su clase es de 0 créditos y deja trabajos que requieren mucho esfuerzo. No lo recomiendo para introvertidos, hay que grabarse para varios cortos y todo el mundo ve sus video en clase xd. El curso se disfruta'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '87f0ce972c6c8f592f17a07d8e1831eb24ea6018a592c77cf00bb1a8cb5999fa'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'NO califica duro, es pura vida, cómico, hay algunos trabajos que para lo que valen el curso son un poco largos pero tiempo más no difíciles, con eso se compensa un poco. En general todo bien.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2021-06-27T00:00:00+00:00'::TIMESTAMPTZ, '23f5ab62575d58238591a290841594849cf63f1e036f90a91fd322c0586bea15'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'Se disfrutan las clases con este profe. No califica dura. Y hace cosas muy interesantes y entretenidas. Solo que para ser un curso de 0 créditos, deja trabajos un poco largos(no difíciles pero sí requieren tiempo).'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Deja trabajos largos']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, '645428544c44cf910895b8d6a245ee394539e0547485ef92cd46861b149b5228'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Virtual. Excelente profe, se ve que ama lo que hace. Ha sabido llevar el curso muy bien y es muy creativo. Hasta me gustó el curso, lástima que sólo 1 vez se puede llevar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2021-01-03T00:00:00+00:00'::TIMESTAMPTZ, 'b3f6d4ee0905f1e60a046e369b537711934f0971a9e4ec7eebe5241dfbce75bb'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Es muy buen profe, en la clase se disfruta mucho y se aprende bastante. Por lo general pide trabajos que requieren algo de esfuerzo, pero no califica para nada duro.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2020-12-24T00:00:00+00:00'::TIMESTAMPTZ, 'a76b5f1240434f00cca59ecf36be70589c01e869369e2b60f9c70b9e04f386c1'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'Sus trabajos requieren de mucho tiempo.No califica duro. Es buen profe'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Requiere mucha lectura', 'Tomaría su clase nuevamente']::TEXT[], '2020-09-01T00:00:00+00:00'::TIMESTAMPTZ, 'ee5fcfe0e63c364a9e726509997f998a12ec2407b5f36b8f973aae0b393f28cd'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'Es un buen profe es exigente en el trabajo final, pero en realidad aprendes mucho, lo recomiendo!!!'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '7ff28f1e857daf47c6484112676de88c7bb2870436a6417b2df1ea58823a5af3'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'En modalidad virtual es sencillo, prácticamente es tomar fotografías y realizar 5 reportes, como trabajo final hacer un cortometraje, eso si lleva trabajo y puede que te quite tiempo ya que por segundo son 12 fotografias o mas y en total hay que hacer , 35 s minimo. Si se aprende y se disfruta.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-22T00:00:00+00:00'::TIMESTAMPTZ, '59f53a6731a892a1ef3e59bef9cb2c88acae81b7c876f9f10404f13edf4c6683'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Como persona, es muy buena gente. Desgraciadamente, si cae en la categoría de profesores que creen que su curso vale más que los de 1 crédfito en adelante. Para ser un curso de 0 créditos si pide bastante. Pero al menos, se puede disfrutar de las películas que se ven en el curso.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '7556a4b7f38dac039cec5a84e959328024430f3b92aa6b8c89b827cfe0e9c5da'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'Al principio el curso fue aburrido porque era oírlo hablar, pero después se hizo bastante divertido con los proyectos en grupo. No ocupa ser un crack en artes, el curso es regalado. Lo único son los reportes pero no quitan mucho tiempo.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'La participación importa']::TEXT[], '2020-01-08T00:00:00+00:00'::TIMESTAMPTZ, '5a7c4eeb3231191dbd7ad3c537a8007f6d91335bbab64bf2c96c23898c574358'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'No hay exámenes, sólo trabajos en clase y si uno se atrasa ahí sí para la casa. Es muy cerrado, él "nunca se equivoca", entonces hay que adaptarse a lo que él diga y punto'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2019-06-18T00:00:00+00:00'::TIMESTAMPTZ, '19122049e7f28ad0e9264ac98009bec87363f0cabb2d41ef028158fe26e2e643'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Es un curso muy interesante y se aprenden bastantes cosas. Sólo hay un trabajo final (el cortometraje) y no quita demasiado tiempo. Recomendado!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-14T00:00:00+00:00'::TIMESTAMPTZ, '44031819baa876960f71d96aa369ee5e64b9bf5d7b0d0d6cb1536217638188c0'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'Si no es bueno en las artes ni se le ocurra matricular. Todo tiene que quedar como a él le guste. El curso con él quita demasiado tiempo. Deja muchísimo trabajo para un curso de 0 créditos. No vale la pena.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2018-06-29T00:00:00+00:00'::TIMESTAMPTZ, '01bef196dcf2a3eaa1bec6e92df10f97a609027a5361d861edec33be537ed8a0'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Súper recomendado, los proyectos son muy chivas y no quitan mucho tiempo porque todo se trabaja en clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '50d05c1477dc5169b0560d4f40d5896d87f84b9acf420b1d574e133d1186aca3'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-11-29T00:00:00+00:00'::TIMESTAMPTZ, '82bd901da79677230693fe059a45af32ee6c86a5a0ce68da77c207c47dfbe6bf'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Se necesita MUCHO TIEMPO, pero se pasa FÁCIL. Pero como objetivo de aprender sobre cine, queda debiendo, no puedo creer que desprecie un genero del cine solo porque le aburre, esperaba clases en donde se comentaran la películas y no solo verlas. Pero si la matriculó solo para pasar no se preocupe.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes', 'Clases excelentes']::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '60651c30212ccfcf6496ad448e3f8431b16189843eddf1c6fda7dcff6d63b2a2'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'El mae, es bueno, todo va super chill al inicio, pero al final se pone fuerte, escojan bien su grupo para el cortometraje.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2017-06-16T00:00:00+00:00'::TIMESTAMPTZ, '49f7ef6e40d47823df664b199bf6402a0578902f54ae6f6f48aa5bdfcdce5bb1'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'Jode demasiado, uno no recibe artes visuales, recibe cine'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'a409d193c1b7913fd0c62cd3e254c886c1e89ede8ce3115262ed7a1a08446291'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Las clases son muy relax, hasta que llega el trabajo final, el proyecto es un poco largo(hacer un cortometraje), llévelo si tiene tiempo.Ademas es muy rudo en cuanto a críticas con respecto al proyecto.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, '02708f2ee41fdefc136e3c310f9c7657f627ce6087fd17a72743266f0643fe9d'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'Buen profe, las primeras lecciones son tranqulas, pero una vez que se empieza con el proyecto final es muy criticón, regaña al frente de todos y lo hace sentir muy mal...'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchos proyectos grupales']::TEXT[], '2017-06-11T00:00:00+00:00'::TIMESTAMPTZ, '4eaf3ab6ef5916c7b17ddf6f5cc38cca586755666f3739501d56c38ff30e03a5'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'Es muy buen profesor, durante el desarrollo de los proyectos está constantemente sugiriendo ideas. La clase es entretenida. El único inconveniente: el curso no es realmente de 0 créditos. Los proyectos requieren bastante tiempo y solicita la asistencia a galerías de arte cómo parte de la nota.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2017-06-06T00:00:00+00:00'::TIMESTAMPTZ, '78fee30e95d19d932ca86aa71a533bc9afbbaaf68d99187afaf0250adff734bc'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Es demasiado el tiempo que se necesita extraclase para ser un curso de cero créditos. Si la agarra con tu grupo, te odiará el resto del semestre a pesar de que hagás todo bien.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2017-06-01T00:00:00+00:00'::TIMESTAMPTZ, 'c8a72c6b3b1af0db86f61b68f72c094b84abd9bdb43b3cb712b2b3ddcbfb1017'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Es súper interesante la clase con el, lo recomiendo :)'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2017-05-09T00:00:00+00:00'::TIMESTAMPTZ, '1888d9e45918d53ad4492977e63fa670b2a1d8354bad691b0031178e0ea34835'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Quita mucho tiempo para ser 0 créditos y las primeras clases es llegar y ver una película (a veces buena a veces no, depende del gusto) así que no es una clase a la que uno pueda llegar y entretenerse'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-02-01T00:00:00+00:00'::TIMESTAMPTZ, '703600d2b722225a167778ead209f4138bb45c93473e7f8ae282ed9d2d95f715'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'Súper buena gente. Escucha al grupo si quiere cambiar algo del plan, y la clase se amolda según las opiniones de los grupos. Califica bien y se hace entretenida la clase, aunque los proyectos se pueden hacer un poco largos'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-25T00:00:00+00:00'::TIMESTAMPTZ, '6e232604713d9b87594d309c7b07a5c0e09391e7be109019d26cc2d72f29cc0e'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador']::TEXT[], '2016-11-17T00:00:00+00:00'::TIMESTAMPTZ, 'ba2076cb9c1f207a338d5ae8fc93eebb11b8d660e1b88580b65530fe059e70f8'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Con el mae se pasa fácil Pero las clases magistrales (para explicar materia) es un bostezo Y es un toque desordenado'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2016-08-01T00:00:00+00:00'::TIMESTAMPTZ, '790a90791e0ff22bb68d23bf80d7bc5c3366d3b706eea4cf27ebcde01ef1f512'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Es bastante bueno, al final se hace un cortometraje y eso quita tiempo, fuera de eso es muy buena opción.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '63060200a2463266e9b0d33aa63176db79cd0de4f0ee91c781383fe6367df9a9'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'en la clase se ven películas muy buenas, y los trabajos son pocos y sencillos, explica muy bien la clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '2319ecdfdcba67785cde43aa4ca797cba967fa4c2e206292a27243eab61effa4'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'Muy buen profe, la clase estuvo muy divertida y aprendimos mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, '69f462d0e5c1469a7fe0ef20d46e7e8ddab1227fa472d6c2743f37df0a49fe0c'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Busca innovar a la hora de enseñar, hace proyectos divertidos.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-06T00:00:00+00:00'::TIMESTAMPTZ, '0b7b8a7ee432357b70dd576e3439b66dc28929044aac50b0435849b380ab6305'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'El curso es ver películas sin obligación de ponerles atención. Pero las pelis son muy buenas... Un examen y trabajo final muy sencillo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'fe854dd533396830410d59b508e69d4d2059a0505fb8dd81c499130fd3b0acfe'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-30T00:00:00+00:00'::TIMESTAMPTZ, '7566af1b2fd18d054105829b9d65b76db3fa49d79ef52230dfcc27b2deb6202f'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'NUNCA matriculen este curso si tienen un semestre pesado, el profe hace de un curso de 0 créditos que uno tengan que palmarla terminando los proyectos. No lo recomiendo para nada. Además de 5 visitas extraclase obligatorias a galerías de arte.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'b1a24a6b10b672810897d645b3084a166f29181fe668b32c93dd5fac7c78bd5d'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Super facil y entretenido el curso ademas el mae es muy tuanis y un exelente artista 100% recomendando'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'e3aace69a77dcecfab9501dd8853e587d5d9dcfbab89024b5396c2cc52edbf92'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'Si quiere pasar el curso sin hacer muchas cosas, con el. Es muy buena persona y no deja muchos trabajos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, '3cd1b1227ca6c87f6a748abcd50e62386596b4ae946936b5b22a1027094c076a'::TEXT, ARRAY[504]::BIGINT[]),
    (173::BIGINT, 'Excelente Profesor!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-17T00:00:00+00:00'::TIMESTAMPTZ, '0d9abec5988be89d4480a17f838edf176e05244db544580ab85f033d8a933fca'::TEXT, ARRAY[501]::BIGINT[]),
    (173::BIGINT, 'El mae muy chiva, clases entretenidas y trabajos chivas'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-09T00:00:00+00:00'::TIMESTAMPTZ, 'a916a0bebe8cfa329543222e06d6d7b29122c51650199be596cb1507319c70b9'::TEXT, ARRAY[501]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
